package game

import (
	"math"
	"testing"
)

// A drive recorded once, replayed here. The expected finish is the exact bits of
// the rover's final position and time, taken on amd64. It must pass unchanged
// under GOOS=js GOARCH=wasm (`make test-wasm`), because the server replays what a
// browser recorded: any difference in the maths between the two would reject
// honest wins.
var goldenDrives = []struct {
	level           int
	samples, stars  int
	timeBits, xBits uint64
	inputs          string
}{
	{1, 2, 1, 0x402873333333330b, 0x4053ee124405d8a9,
		""},
	{21, 3, 2, 0x405123333333337b, 0x4061837c207e6ae8,
		""},
}

func TestReplayGolden(t *testing.T) {
	for _, g := range goldenDrives {
		r, err := Replay(GetLevel(g.level), referenceDesign(), g.inputs)
		if err != nil {
			t.Fatalf("level %d: %v", g.level, err)
		}
		if r.Outcome != Won || r.SamplesGot() != g.samples || r.Stars() != g.stars {
			t.Errorf("level %d: %s, %d samples, %d stars", g.level, r.Outcome.Message(), r.SamplesGot(), r.Stars())
		}
		if got := math.Float64bits(r.Time); got != g.timeBits {
			t.Errorf("level %d: finish time bits %016x, want %016x", g.level, got, g.timeBits)
		}
		if got := math.Float64bits(r.Rover.Center().X); got != g.xBits {
			t.Errorf("level %d: final x bits %016x, want %016x", g.level, got, g.xBits)
		}
	}
}
